    "button_at_top_left_2": "ڈسپلے کے اوپر بائیں جانب ایک بٹن جو لمبائی، رقبہ، حجم، کمیت، درجۂ حرارت، رفتار، وقت، ڈیٹا، دباؤ، توانائی، طاقت، زاویے، ایندھن کی کفایت، قوت، مروڑ، کثافت، تعدد، اسراع، بہاؤ کی شرح، کرنٹ، وولٹیج، چارج، مزاحمت، گنجائش، امالہ، مقناطیسی میدان، معیارِ حرکت اور تابکاری کی اکائیاں تبدیل کرتا ہے۔ دکھائی گئی قدر وہ ہے جس سے شروع کرنا ہے؛ تبدیل شدہ قدر کو ڈسپلے میں ڈالنے کے لیے اس پر کلک کریں۔ اس کا تاریخیں ٹیب دو تاریخوں کے درمیان دن گنتا ہے، کسی تاریخ کو سالوں، مہینوں اور دنوں سے آگے بڑھاتا ہے، اور کسی وقت کو دوسرے ٹائم زونز میں دکھاتا ہے۔",
    "button_at_top_left_3": "ڈسپلے کے اوپر بائیں جانب ایک بٹن جو x اور y محوروں پر x کے 25 تک فنکشن، جیسے x^2 – 3 یا 2sin(x)، ان کے جذور، بلند ترین، پست ترین اور تقاطع کے نشانات کے ساتھ بناتا ہے۔ اسے سرکانے کے لیے گھسیٹیں، بڑا چھوٹا کرنے کے لیے اسکرول یا پنچ کریں، اور کسی منحنی یا نقطے پر اشارہ کر کے اس کی قدریں دیکھیں؛ جدول ٹیب انہیں فہرست کرتا ہے۔",
    "button_at_top_left_4": "ڈسپلے کے اوپر بائیں جانب ایک بٹن قالب کے لیے: ان کا مقطع، معکوس، طاقتیں، مجموعے، حاصل ضرب، آئیگن ویلیو، تخفیف شدہ قطاریں، LU اور QR، اور A x = b، 10 × 10 تک، اور سمتیے؛ مخلوط اعداد، جیسے (2 + 3i)(1 – i)، اور ان کی کثیر رقمیوں کے جذور؛ بِٹس میں صحیح اعداد ان کے ہیکساڈیسیمل، آکٹل اور بائنری کے ساتھ، کسی بھی بنیاد میں اعداد، متن اپنے کوڈز کی شکل میں، اور اعداد ڈبل اور فلوٹ کی شکل میں؛ اور صحیح اعداد کے اولین اجزائے ضربی، GCD اور LCM، ماڈیولر حساب، مفرد اعداد، ہر ہندسے تک اعداد، کسریں اور ان کے اعشاریے، اور راؤنڈنگ۔",
    "button_at_top_left_5": "ڈسپلے کے اوپر بائیں جانب ایک بٹن جو x کے لیے مساوات یا عدم مساوات، کثیر رقمی، دو یا تین خطی مساواتیں یا دو منحنی حل کرتا ہے، موڑ کے نقاط، تکمل، ڈھلوانیں، ∞ تک مجموعے اور حاصل ضرب، حدیں، ٹیلر سلسلے، منحنیوں کے درمیان رقبے، قوس کی لمبائیاں اور تفرقی مساواتیں، نارمل، t، χ²، F، دو رقمی، پوآسوں اور دیگر تقسیموں کے امکانات، اعتماد وقفے، اور وقت کے ساتھ رقم، NPV اور IRR، قرض اور بچت، APR اور APY، بانڈ، فرسودگی، نفع نقصان کا توازن، مہنگائی اور فیصد تبدیلی نکالتا ہے؛ اور جیومیٹری: کسی مثلث کے اضلاع اور زاویوں میں سے کوئی تین سے، اشکال، ٹھوس اجسام، نقاط اور خطوط، اور کثیر الاضلاع۔",
    "button_at_top_left_6": "ڈسپلے کے اوپر بائیں جانب ایک بٹن دوری جدول کے لیے: تمام 118 عناصر ہلکے رنگوں میں قسم، حالت، بلاک یا برق منفیت کے مطابق، اور کسی پر کلک کرنے سے اس کی کمیت، الیکٹرانی ترتیب، نقطۂ پگھلاؤ اور جوش، کثافت، تکسیدی حالتیں اور اس کا ایٹم اپنے خولوں کے ساتھ بنا ہوا، جو صفحے جتنا بڑا نکالا جا سکتا ہے۔ اور کسی فارمولے کی مولر کمیت، متوازن مساواتیں، کسی تعامل کی مقداریں اور اس کا محدود کرنے والا متعامل، تجرباتی فارمولے، مولیریٹی، تحلیل، pH اور بفر، گیسوں کے قوانین، حرارت اور نصف زندگی۔",
    "button_at_top_left_7": "ڈسپلے کے اوپر بائیں جانب ایک بٹن الیکٹرانکس کے لیے، مزاحم کے رنگ کوڈ اور اوہم کے قانون سے لے کر LED کے مزاحم، تاریں، بیٹریاں، کیپیسیٹر، ٹرانزسٹر، آپ-ایمپ، 555، فلٹر، SMD کوڈ اور ڈیسیبل تک؛ یکساں اسراع پر حرکت، اپنے راستے کے ساتھ پروجیکٹائل، دائری حرکت، پنڈولم اور گردش؛ قوتیں، تصادم، دھکا، توانائی، مروڑ اور لیور، تجاذب، مزاحمتِ ہوا، چارج، مقناطیسی میدان اور امالہ؛ لہریں، ساکن لہریں، عدسے، انعطاف، مداخلت، پولرائزیشن، ڈوپلر اثر اور فوٹون؛ حرارت، گیس کے سالمات، حرارتی انجن، تناؤ اور سیال؛ اور E = mc²، بندھن توانائی، فوٹو الیکٹرک اثر، اضافیت، غیر یقینی اصول سے سرنگی اثر تک کوانٹم طبیعیات، ہائیڈروجن کا طیف اور تابکار تنزل۔ بہت سے کارڈ جو نکالتے ہیں اسے بناتے بھی ہیں۔",
