    "then_shift_does_same": "پھر Shift+A وہی کرتا ہے۔ Shift+A سے Shift+J مساوات میں حرف ڈالتے ہیں، 2A + B، جو اس کی رکھی ہوئی قدر سے حل ہوتا ہے۔ تاریخچے کے متغیرات ٹیب میں ہر ایک کا کارڈ ہے: اس کے خانے میں قدر لکھیں، STO سطر کا نتیجہ اس میں رکھتا ہے، اور اس کا تیر اسے مساوات میں ڈالتا ہے؛ صاف ہر ایک کو واپس 0 کر دیتا ہے۔ ڈسپلے، کسی پینل کی قدر یا تاریخچے پر رائٹ کلک میں متغیر میں محفوظ کریں ہے؛ ڈسپلے پر متغیر ڈالیں کوئی متغیر ڈالتا ہے۔ یہ چسپاں شدہ متن، گراف، سولور اور ہر اس خانے میں کام کرتے ہیں جو عدد لیتا ہے: فارمولے کا، کنورٹر کا، گراف کا اور اعداد کا؛ کسی خانے پر ماؤس لے جائیں تو دیکھیں کہ اس کے متغیر کیا رکھتے ہیں۔ EE ᴇ کی شکل میں دکھتا ہے، 5ᴇ3، اس لیے 2E کا مطلب 2 × E ہے۔",
