    "click_bars_at_top": "ڈسپلے کے اوپر بائیں جانب بارز پر کلک کریں اور اعداد کی فہرست لکھیں یا چسپاں کریں، اسپریڈشیٹ کا کالم بھی۔ کسی نتیجے پر کلک کریں تو وہ آپ کے حساب میں استعمال ہوتا ہے، یا اس پر ماؤس رکھیں تو وہ کیا ہے اور اس کی پوری قدر دیکھیں، داخل کریں اور کاپی کے ساتھ۔ فہرست اپنے اعداد کے درمیان کیا ہے خود ڈھونڈ لیتی ہے؛ اس کی جگہ پینل کے اوپر نئی سطریں، ٹیب، خالی جگہیں، کاما، سیمی کولن، پائپ یا کولن چنیں، اور 1,234.5، 1 234,5 یا $1,200 لکھا ہوا عدد پورا پڑھا جاتا ہے۔",
