    "pairs_takes_x_and": "جوڑے ہر سطر پر x اور y لیتے ہیں، 1 2 یا 1, 2، یا اسپریڈشیٹ سے چسپاں دو کالم، ان کے اوسط، معیاری انحراف، مجموعے، Σxy اور باہمی تغیر، اسپیئرمین کا ρ، اور خانے کے نیچے چنی گئی قسم کا کم از کم مربعات سے بہترین بیٹھنے والا منحنی: خطی، y = a + bx، اپنی ڈھلوان، تقاطع، باہمی تعلق r اور r² کے ساتھ؛ دو درجی؛ سہ درجی؛ قوت نمائی، y = a · bˣ؛ قوت، y = a · xᵇ؛ لوگارتھمی، y = a + b ln x؛ یا لاجسٹک، y = c / (1 + a e^(–bx))۔ اس کی مساوات انتخاب کے ساتھ ہے، اور وہ نتائج کے اوپر جوڑوں سے گزرتی ہوئی بنی ہے۔",
