    "of_chromatography_microscope_s": "کروماٹوگرافی کا؛ خوردبین کی بڑائی اور منظر کا میدان؛ جیل سے بینڈ کا سائز، DNA یا SDS-PAGE پر پروٹین کا؛ تبدیلی کی کارکردگی؛ پلیٹوں میں بیج ڈالنا، پلیٹ بنی ہوئی؛ MOI، اور پوآسوں سے متاثرہ خلیے؛ ریڈیو آئسوٹوپ، ان کا تنزل اور ڈھال؛ اور بفر، کیا تولنا ہے اور کتنا تیزاب یا اساس ڈالنا ہے۔",
