    "results_shown_with_13": "نتائج 13 بامعنی ہندسوں کے ساتھ دکھائے جاتے ہیں، اس لیے یہ چھوٹی راؤنڈنگ کی غلطیاں نظر نہیں آتیں: 0.1 + 0.2 سے 0.3 دکھتا ہے، 0.30000000000000004 نہیں۔ ڈگری میں زاویے وہاں ٹھیک قدریں دیتے ہیں جہاں انہیں دینی چاہییں: sin 180 صفر ہے اور cos 60 برابر 0.5۔",
    "problem_javascript_uses_64": "مسئلہ یہ ہے کہ JavaScript ہر عدد کو رکھنے کے لیے ڈیٹا کے 64 بِٹ استعمال کرتی ہے، جو 18446744073709551616 مختلف بِٹ نمونے رکھ سکتے ہیں: 1 بِٹ اشارے کے لیے، 11 بِٹ قوت نما کے لیے اور 52 بِٹ ہندسوں کے لیے۔ یہ تقریباً –1.7976931348623157e+308 سے 1.7976931348623157e+308 تک کی قدروں کو احاطہ کرتا ہے، سب سے چھوٹے معمولی عدد 2.2250738585072014e–308 کے ساتھ اور اس سے بھی چھوٹے 5e–324 تک۔",
    "smaller_precision_value_with": "کچھ بِٹس کو قوت نما بنا کر کم درستی کی قدر ہی اس دائرے میں سمانے کا طریقہ ہے (یہ 16 بِٹ میں بھی چھوٹے دائرے اور کم درستی کے ساتھ کیا جا سکتا ہے)۔ نتیجہ یہ ہے کہ یہ دائرے کی کسی بھی قدر کا اندازہ لگا سکتی ہے مگر سب کو ٹھیک ٹھیک ظاہر نہیں کر سکتی، کیونکہ حقیقی اعداد کے لحاظ سے کسی بھی دو دی گئی قدروں کے درمیان لامحدود قدریں ہوتی ہیں۔",
