    "since_only_tiny_amounts_2": "چونکہ لارنسیم نہایت تھوڑی مقدار میں بنی ہے، فی الحال بنیادی سائنسی تحقیق کے علاوہ اس کا کوئی استعمال نہیں۔",
    "lawrencium_was_created_by": "لارنسیم مارچ 1961 میں چار امریکی سائنس دانوں، البرٹ گیورسو، تورب یورن سیکیلینڈ، المون ای لارش اور رابرٹ ایم لیٹیمر، نے بنائی۔",
    "silvery": "چاندی جیسا",
    "rutherfordium": "ردرفورڈیم",
    "due_to_small_amounts_4": "تھوڑی مقدار میں تیار ہونے اور اس کی مختصر نصف زندگی کی وجہ سے، فی الحال بنیادی سائنسی تحقیق کے علاوہ رودرفورڈیم کا کوئی استعمال نہیں۔",
    "scientists_working_at_joint": "روس کے شہر دبنا میں جوائنٹ انسٹیٹیوٹ فار نیوکلیئر ریسرچ میں کام کرنے والے سائنس دانوں نے 1964 میں پہلی بار رودرفورڈیم کی تیاری کی اطلاع دی۔",
    "dubnium": "ڈبنیم",
    "due_to_small_amounts_5": "تھوڑی مقدار میں تیار ہونے اور اس کی مختصر نصف زندگی کی وجہ سے، فی الحال بنیادی سائنسی تحقیق کے علاوہ ڈبنیم کا کوئی استعمال نہیں۔",
    "scientists_working_at_joint_2": "روس کے شہر دبنا میں جوائنٹ انسٹیٹیوٹ فار نیوکلیئر ریسرچ میں کام کرنے والے سائنس دانوں نے 1967 میں پہلی بار ڈبنیم کی تیاری کی اطلاع دی۔",
    "seaborgium": "سیبورگیم",
    "since_only_few_atoms": "چونکہ سیبورگیم کے صرف چند ایٹم بنے ہیں، فی الحال بنیادی سائنسی تحقیق کے علاوہ سیبورگیم کا کوئی استعمال نہیں۔",
    "seaborgium_was_first_produced": "سیبورگیم پہلی بار 1974 میں کیلیفورنیا کے شہر برکلے کی لارنس برکلے لیبارٹری میں کام کرنے والی البرٹ گیورسو کی قیادت میں سائنس دانوں کی ٹیم نے تیار کی۔",
    "bohrium": "بوہریم",
