    "hassium": "ہاسیم",
    "since_only_small_amounts_4": "چونکہ ہیسیم صرف تھوڑی مقدار میں بنی ہے، فی الحال بنیادی سائنسی تحقیق کے علاوہ اس کا کوئی استعمال نہیں۔",
    "hassium_was_first_produced": "ہیسیم پہلی بار 1984 میں جرمنی کے شہر ڈارمشٹاٹ کی Gesellschaft für Schwerionenforschung میں کام کرنے والے پیٹر آرمبرسٹر، گوٹفرائیڈ منزنبرگ اور ان کی ٹیم نے تیار کی۔",
    "meitnerium": "مائٹنیریم",
    "since_only_small_amounts_5": "چونکہ مائٹنیریم صرف تھوڑی مقدار میں بنی ہے، فی الحال بنیادی سائنسی تحقیق کے علاوہ اس کا کوئی استعمال نہیں۔",
    "meitnerium_was_first_produced": "مائٹنیریم پہلی بار 1982 میں جرمنی کے شہر ڈارمشٹاٹ کی Gesellschaft für Schwerionenforschung میں کام کرنے والے پیٹر آرمبرسٹر، گوٹفرائیڈ منزنبرگ اور ان کی ٹیم نے تیار کی۔",
    "darmstadtium": "ڈارمسٹیڈیم",
    "since_only_few_atoms_3": "چونکہ ڈارمشٹاٹیم کے صرف چند ایٹم بنے ہیں، فی الحال بنیادی سائنسی تحقیق کے علاوہ اس کا کوئی استعمال نہیں۔",
    "darmstadtium_was_first_produced": "ڈارمشٹاٹیم پہلی بار 9 نومبر 1994 کو جرمنی کے شہر ڈارمشٹاٹ کی Gesellschaft für Schwerionenforschung میں کام کرنے والے پیٹر آرمبرسٹر، گوٹفرائیڈ منزنبرگ اور ان کی ٹیم نے تیار کیا۔",
    "roentgenium": "رونٹجینیم",
    "since_only_few_atoms_4": "چونکہ رونٹجینیم کے صرف چند ایٹم بنے ہیں، فی الحال بنیادی سائنسی تحقیق کے علاوہ اس کا کوئی استعمال نہیں۔",
    "roentgenium_was_first_produced": "رونٹجینیم پہلی بار 1994 کے آخر میں جرمنی کے شہر ڈارمشٹاٹ کی Gesellschaft für Schwerionenforschung میں کام کرنے والے پیٹر آرمبرسٹر، گوٹفرائیڈ منزنبرگ اور ان کی ٹیم نے تیار کیا۔",
