    "copernicium_was_first_produced": "کوپرنیشیم پہلی بار 9 فروری 1996 کو جرمنی کے شہر ڈارمشٹاٹ کی Gesellschaft für Schwerionenforschung میں کام کرنے والے پیٹر آرمبرسٹر، گوٹفرائیڈ منزنبرگ اور ان کی ٹیم نے تیار کیا۔",
