    "on_december_6_2000": "6 دسمبر 2000 کو روس کے شہر دبنا میں جوائنٹ انسٹیٹیوٹ فار نیوکلیئر ریسرچ میں کام کرنے والے سائنس دانوں نے، امریکی محکمۂ توانائی کی لارنس لیورمور نیشنل لیبارٹری کے سائنس دانوں کے ساتھ مل کر، لیورموریم کی تیاری کا اعلان کیا۔",
